// Contour-map background: faint contour lines traced from real elevation data, drawn onto a canvas.
// The data file is generated by scripts/topo_background.py; src/components/site/topo-background.tsx draws it.

export type TopoLabel = { name: string; kind: "peak" | "place"; feet: number | null; x: number; y: number };

export type TopoTexture = {
  interval: number; // metres between contours
  index: number; // every n-th contour is drawn a little stronger, like the index lines on a printed map
  lineAlpha: number;
  lineWidth: number; // CSS pixels
  colour: "flow" | "level"; // a gradient along the page, or a colour per height
  view: [number, number, number, number]; // the framed area, as fractions of the grid
  dem: { w: number; h: number; min: number; max: number; data: string }; // base64 little-endian uint16 grid
  labels?: TopoLabel[];
};

export type TopoPalette = { maroon: string; orange: string; olive: string; cyan: string };

export type TopoField = {
  heights: Float32Array;
  cellLow: Float32Array;
  cellHigh: Float32Array;
  cols: number;
  rows: number;
  step: number;
  low: number;
  high: number;
  place: (x: number, y: number) => [number, number];
};

export type TopoOptions = {
  palette: TopoPalette;
  strength: number;
  phase?: number; // moves every contour by this many intervals; changing it makes the lines flow
  labels?: boolean;
  labelColour?: string;
  labelFont?: string; // a CSS font shorthand for the summit labels
};

const decoded = new WeakMap<TopoTexture["dem"], Float32Array>();

function elevations(dem: TopoTexture["dem"]): Float32Array {
  const cached = decoded.get(dem);
  if (cached) return cached;
  const binary = atob(dem.data);
  const values = new Float32Array(binary.length / 2);
  const range = dem.max - dem.min;
  for (let i = 0; i < values.length; i++) {
    const raw = binary.charCodeAt(2 * i) | (binary.charCodeAt(2 * i + 1) << 8);
    values[i] = dem.min + (raw / 65535) * range;
  }
  decoded.set(dem, values);
  return values;
}

/**
 * Samples the elevation grid for a canvas of the given size. The framed view keeps its centre and grows (or, at
 * the edge of the data, shrinks) to the canvas shape, so the map always fills the frame without stretching.
 */
export function sampleTopo(texture: TopoTexture, width: number, height: number, step = 5): TopoField {
  const { dem } = texture;
  const z = elevations(dem);
  const [x0, y0, x1, y1] = texture.view;
  let viewWidth = (x1 - x0) * dem.w;
  let viewHeight = (y1 - y0) * dem.h;
  if (viewWidth / viewHeight < width / height) viewWidth = viewHeight * (width / height);
  else viewHeight = viewWidth / (width / height);
  const fit = Math.min(1, dem.w / viewWidth, dem.h / viewHeight);
  viewWidth *= fit;
  viewHeight *= fit;
  // Clamped at 0 on both sides: when the view spans the whole grid, rounding can make dem.w - viewWidth a hair negative.
  const left = Math.max(0, Math.min(((x0 + x1) / 2) * dem.w - viewWidth / 2, dem.w - viewWidth));
  const top = Math.max(0, Math.min(((y0 + y1) / 2) * dem.h - viewHeight / 2, dem.h - viewHeight));

  const cols = Math.ceil(width / step) + 1;
  const rows = Math.ceil(height / step) + 1;
  const heights = new Float32Array(cols * rows);
  let low = Infinity;
  let high = -Infinity;
  for (let row = 0; row < rows; row++) {
    for (let col = 0; col < cols; col++) {
      const sx = Math.min(dem.w - 1.001, left + ((col * step) / width) * viewWidth);
      const sy = Math.min(dem.h - 1.001, top + ((row * step) / height) * viewHeight);
      const ix = Math.floor(sx);
      const iy = Math.floor(sy);
      const fx = sx - ix;
      const fy = sy - iy;
      const i = iy * dem.w + ix;
      const value = z[i] * (1 - fx) * (1 - fy) + z[i + 1] * fx * (1 - fy) + z[i + dem.w] * (1 - fx) * fy + z[i + dem.w + 1] * fx * fy;
      heights[row * cols + col] = value;
      if (value < low) low = value;
      if (value > high) high = value;
    }
  }

  // Each cell's lowest and highest corner, so drawing can skip cells a contour cannot cross.
  const cellLow = new Float32Array((cols - 1) * (rows - 1));
  const cellHigh = new Float32Array((cols - 1) * (rows - 1));
  for (let row = 0; row < rows - 1; row++) {
    for (let col = 0; col < cols - 1; col++) {
      const i = row * cols + col;
      const a = heights[i], b = heights[i + 1], c = heights[i + cols], d = heights[i + cols + 1];
      cellLow[row * (cols - 1) + col] = Math.min(a, b, c, d);
      cellHigh[row * (cols - 1) + col] = Math.max(a, b, c, d);
    }
  }

  const place = (fx: number, fy: number): [number, number] => [
    ((fx * dem.w - left) / viewWidth) * width,
    ((fy * dem.h - top) / viewHeight) * height,
  ];
  return { heights, cellLow, cellHigh, cols, rows, step, low, high, place };
}

function rgb(hex: string): [number, number, number] {
  return [1, 3, 5].map((i) => parseInt(hex.slice(i, i + 2), 16)) as [number, number, number];
}

function rampColour(ramp: string[], t: number): string {
  const f = Math.min(0.9999, Math.max(0, t)) * (ramp.length - 1);
  const k = Math.floor(f);
  const a = rgb(ramp[k]);
  const b = rgb(ramp[k + 1]);
  return `rgb(${a.map((v, j) => Math.round(v + (b[j] - v) * (f - k))).join(",")})`;
}

// Marching squares: adds the segments of one contour level to the current path.
function traceLevel(ctx: CanvasRenderingContext2D, field: TopoField, level: number): void {
  const { heights: h, cellLow, cellHigh, cols, rows, step } = field;
  const t = (a: number, b: number) => (level - a) / (b - a || 1e-9);
  for (let row = 0; row < rows - 1; row++) {
    for (let col = 0; col < cols - 1; col++) {
      const cell = row * (cols - 1) + col;
      if (level < cellLow[cell] || level >= cellHigh[cell]) continue; // no corner above, or none at or below
      const i = row * cols + col;
      const a = h[i], b = h[i + 1], d = h[i + cols], e = h[i + cols + 1];
      const code = (a > level ? 8 : 0) | (b > level ? 4 : 0) | (e > level ? 2 : 0) | (d > level ? 1 : 0);
      if (code === 0 || code === 15) continue;
      const x = col * step;
      const y = row * step;
      const top: [number, number] = [x + step * t(a, b), y];
      const right: [number, number] = [x + step, y + step * t(b, e)];
      const bottom: [number, number] = [x + step * t(d, e), y + step];
      const left: [number, number] = [x, y + step * t(a, d)];
      const segment = (p: [number, number], q: [number, number]) => {
        ctx.moveTo(p[0], p[1]);
        ctx.lineTo(q[0], q[1]);
      };
      switch (code) {
        case 1: case 14: segment(left, bottom); break;
        case 2: case 13: segment(bottom, right); break;
        case 3: case 12: segment(left, right); break;
        case 4: case 11: segment(top, right); break;
        case 6: case 9: segment(top, bottom); break;
        case 7: case 8: segment(left, top); break;
        case 5: segment(left, top); segment(bottom, right); break;
        case 10: segment(top, right); segment(left, bottom); break;
      }
    }
  }
}

/**
 * Draws the contours. Call sampleTopo again only when the canvas size changes. A redraw costs a few milliseconds at
 * laptop sizes, so callers redraw on scroll only when the phase has moved a visible amount.
 */
export function drawTopo(
  ctx: CanvasRenderingContext2D,
  width: number,
  height: number,
  field: TopoField,
  texture: TopoTexture,
  options: TopoOptions,
): void {
  const { interval, index } = texture;
  const phase = options.phase ?? 0;
  const ramp = [options.palette.maroon, options.palette.orange, options.palette.olive, options.palette.cyan];
  let flow: CanvasGradient | null = null;
  if (texture.colour === "flow") {
    // Colour moves from the lower left to the upper right of the screen.
    flow = ctx.createLinearGradient(0, height, width, height * 0.2);
    ramp.forEach((colour, i) => flow?.addColorStop(i / (ramp.length - 1), colour));
  }
  ctx.save();
  ctx.lineCap = "round";
  ctx.lineJoin = "round";
  // Contour k sits at (k + phase) * interval, so as the phase grows each line climbs steadily and the index
  // lines stay with their contour.
  const first = Math.ceil(field.low / interval - phase);
  const last = Math.floor(field.high / interval - phase);
  for (let k = first; k <= last; k++) {
    const level = (k + phase) * interval;
    const major = index > 0 && ((k % index) + index) % index === 0;
    ctx.strokeStyle = flow ?? rampColour(ramp, (level - field.low) / (field.high - field.low || 1));
    ctx.globalAlpha = Math.min(1, texture.lineAlpha * options.strength * (major ? 1.7 : 1));
    ctx.lineWidth = texture.lineWidth * (major ? 1.5 : 1);
    ctx.beginPath();
    traceLevel(ctx, field, level);
    ctx.stroke();
  }
  ctx.restore();

  if (options.labels && texture.labels) {
    // Small, quiet map labels: a summit triangle (or a dot for a place) with the name and published height.
    ctx.save();
    ctx.fillStyle = options.labelColour ?? "#78716c";
    ctx.globalAlpha = 0.8 * Math.min(1, options.strength);
    ctx.font = options.labelFont ?? "10px Georgia, serif";
    ctx.textBaseline = "middle";
    for (const label of texture.labels) {
      const [x, y] = field.place(label.x, label.y);
      const text = label.kind === "peak" && label.feet ? `${label.name} ${label.feet.toLocaleString("en-US")}` : label.name;
      const textWidth = ctx.measureText(text).width;
      const textX = x + textWidth + 10 > width ? x - textWidth - 6 : x + 6;
      if (y < 8 || y > height - 8 || textX < 2 || textX + textWidth > width - 2) continue;
      ctx.beginPath();
      if (label.kind === "peak") {
        ctx.moveTo(x, y - 3);
        ctx.lineTo(x + 3, y + 2.2);
        ctx.lineTo(x - 3, y + 2.2);
        ctx.closePath();
      } else {
        ctx.arc(x, y, 1.6, 0, Math.PI * 2);
      }
      ctx.fill();
      ctx.fillText(text, textX, y);
    }
    ctx.restore();
  }
}
